import{_ as e,o as d,c as l,ak as o}from"./chunks/framework.BfDh7BTc.js";const h=JSON.parse('{"title":"空值安全工具（nullness 包）","description":"","frontmatter":{},"headers":[],"relativePath":"posts/docs/util/nullness/index.md","filePath":"posts/docs/util/nullness/index.md","lastUpdated":1778540647000}'),a={name:"posts/docs/util/nullness/index.md"};function n(c,t,r,i,u,s){return d(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="空值安全工具-nullness-包" tabindex="-1">空值安全工具（nullness 包） <a class="header-anchor" href="#空值安全工具-nullness-包" aria-label="Permalink to “空值安全工具（nullness 包）”">​</a></h1><p>位于 <code>dev.anvilcraft.lib.v2.util.nullness</code>，提供非空/可空类型注解与对应的函数式接口。</p><h2 id="注解" tabindex="-1">注解 <a class="header-anchor" href="#注解" aria-label="Permalink to “注解”">​</a></h2><ul><li><code>@NonnullType</code> – 可用于类型参数的非空声明（<code>javax.annotation.Nonnull</code> 的替代）</li><li><code>@NullableType</code> – 同上，用于可空类型</li><li><code>@FieldsAreNonnullByDefault</code> – 应用于包或类，声明字段默认为非空</li></ul><h2 id="函数式接口" tabindex="-1">函数式接口 <a class="header-anchor" href="#函数式接口" aria-label="Permalink to “函数式接口”">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>对应 Java 类型</th><th>描述</th></tr></thead><tbody><tr><td><code>NonNullSupplier&lt;T&gt;</code></td><td><code>Supplier&lt;T&gt;</code></td><td>不允许返回 null</td></tr><tr><td><code>NonNullConsumer&lt;T&gt;</code></td><td><code>Consumer&lt;T&gt;</code></td><td>参数非空</td></tr><tr><td><code>NonNullBiConsumer&lt;T,U&gt;</code></td><td><code>BiConsumer&lt;T,U&gt;</code></td><td>两个参数均非空</td></tr><tr><td><code>NonNullFunction&lt;T,R&gt;</code></td><td><code>Function&lt;T,R&gt;</code></td><td>参数和返回值均非空</td></tr><tr><td><code>NonNullBiFunction&lt;T,U,R&gt;</code></td><td><code>BiFunction&lt;T,U,R&gt;</code></td><td>参数和返回值均非空</td></tr><tr><td><code>NonNullUnaryOperator&lt;T&gt;</code></td><td><code>UnaryOperator&lt;T&gt;</code></td><td>参数和返回值均非空</td></tr></tbody></table><p>所有接口均支持组合（<code>andThen</code>）和静态工厂 <code>noop()</code>（空操作），<code>NonNullSupplier</code> 额外提供 <code>lazy()</code> 与 <code>of(Supplier)</code> 转换。</p><h2 id="版本间导入路径" tabindex="-1">版本间导入路径 <a class="header-anchor" href="#版本间导入路径" aria-label="Permalink to “版本间导入路径”">​</a></h2><p>由于 <code>module.util</code> 在部分版本中未作为独立模块发布，<code>nullness</code> 包的导入路径存在版本差异：</p><table tabindex="0"><thead><tr><th>版本范围</th><th>导入路径</th></tr></thead><tbody><tr><td>1.21.1</td><td><code>import dev.anvilcraft.lib.v2.util.nullness.NonNullSupplier;</code></td></tr><tr><td>1.21.2–1.21.11</td><td><code>import dev.anvilcraft.lib.v2.registrum.util.nullness.NonNullSupplier;</code></td></tr><tr><td>26.1</td><td><code>import dev.anvilcraft.lib.v2.util.nullness.NonNullSupplier;</code>（恢复）</td></tr></tbody></table><blockquote><p>1.21.2–1.21.11 版本中 <code>module.util</code> 因产能限制未同步，nullness 函数式接口被内嵌到 <code>module.registrum</code> 中以保障 Registrum 可独立编译。26.1 中随 <code>module.util</code> 恢复同步，导入路径迁回。</p></blockquote><h2 id="已废弃接口" tabindex="-1">已废弃接口 <a class="header-anchor" href="#已废弃接口" aria-label="Permalink to “已废弃接口”">​</a></h2><ul><li><code>NullableSupplier&lt;T&gt;</code> – 请使用 <code>Supplier&lt;T&gt;</code> 直接标注 <code>@Nullable</code>。</li></ul>',13)])])}const b=e(a,[["render",n]]);export{h as __pageData,b as default};
